package com.medtrack.batch.entity;
import com.medtrack.medicine.entity.Medicine; import com.medtrack.shared.model.BaseEntity; import com.medtrack.supplier.entity.Supplier; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="batches") public class Batch extends BaseEntity { @Column(name="batch_number",nullable=false) private String batchNumber; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="medicine_id",nullable=false) private Medicine medicine; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="supplier_id",nullable=false) private Supplier supplier; @Column(name="manufacturing_date",nullable=false) private LocalDate manufacturingDate; @Column(name="expiry_date",nullable=false) private LocalDate expiryDate; @Column(name="initial_quantity",nullable=false) private int initialQuantity; @Enumerated(EnumType.STRING) @Column(nullable=false) private BatchStatus status; protected Batch(){} public Batch(String no,Medicine med,Supplier sup,LocalDate mfg,LocalDate exp,int qty,BatchStatus status){batchNumber=no;medicine=med;supplier=sup;manufacturingDate=mfg;expiryDate=exp;initialQuantity=qty;this.status=status;} public String getBatchNumber(){return batchNumber;} public Medicine getMedicine(){return medicine;} public Supplier getSupplier(){return supplier;} public LocalDate getManufacturingDate(){return manufacturingDate;} public LocalDate getExpiryDate(){return expiryDate;} public int getInitialQuantity(){return initialQuantity;} public BatchStatus getStatus(){return status;} }
